<!-- eslint-disable vue/multi-word-component-names -->
<template>
	<div v-if="subject !== null" class="ext-neowiki-infobox">
		<div class="ext-neowiki-infobox__header">
			<div class="ext-neowiki-infobox__header__text">
				<div
					class="ext-neowiki-infobox__title"
					role="heading"
					aria-level="2"
				>
					{{ subjectDisplayName( subject ) }}
				</div>
				<!-- Conditional on the badge, not the reverse: a wrapper left behind when the
					badge withholds itself announces as an unnamed level-3 heading. -->
				<div
					v-if="schemaNameBadge !== null"
					class="ext-neowiki-infobox__schema"
					role="heading"
					aria-level="3"
				>
					<SchemaNameDisplay :schema-name="schemaNameBadge" />
				</div>
			</div>
			<CdxButton
				v-if="canEditSubject"
				weight="quiet"
				:aria-label="$i18n( 'neowiki-infobox-edit-link' ).text()"
				@click="openEditor( subjectId )"
			>
				<CdxIcon :icon="cdxIconEdit" />
			</CdxButton>
			<SubjectEditorDialog
				v-if="editingSubject !== null && editingSchema !== null"
				v-model:open="editorOpen"
				:subject="editingSubject as Subject"
				:schema="editingSchema as Schema"
				:on-save="handleSaveSubject"
				:on-create="handleCreateSubject"
				:on-save-schema="handleSaveSchema"
			/>
		</div>
		<div class="ext-neowiki-infobox__content">
			<div
				v-for="( resolved, rowIndex ) in displayRows"
				:key="`${ resolved.sourcePropertyName }-${ rowIndex }`"
				class="ext-neowiki-infobox__item"
			>
				<div class="ext-neowiki-infobox__property">
					<PropertyLabel :property="resolved.propertyDefinition" />
				</div>
				<div class="ext-neowiki-infobox__value">
					<component
						:is="getComponent( resolved.propertyDefinition.type )"
						:key="`${resolved.propertyDefinition.name}${resolved.value}-ext-neowiki-infobox`"
						:value="resolved.value"
						:property="resolved.propertyDefinition"
					/>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup lang="ts">
import { expandUrlDisplayRows } from '@/presentation/urlDisplayRows';
import PropertyLabel from '@/components/common/PropertyLabel.vue';
import { Component, computed, provide } from 'vue';
import { Subject } from '@/domain/Subject.ts';
import { Schema } from '@/domain/Schema.ts';
import { useSchemaStore } from '@/stores/SchemaStore.ts';
import { useLayoutStore } from '@/stores/LayoutStore.ts';
import { NeoWikiServices } from '@/NeoWikiServices.ts';
import SubjectEditorDialog from '@/components/SubjectEditor/SubjectEditorDialog.vue';
import { useSubjectEditor } from '@/composables/useSubjectEditor.ts';
import SchemaNameDisplay from '@/components/common/SchemaNameDisplay.vue';
import { schemaNameToShow } from '@/presentation/schemaNameToShow.ts';
import { subjectDisplayName } from '@/presentation/subjectDisplayName.ts';
import { useSubjectStore, type DependentSubjects } from '@/stores/SubjectStore.ts';
import { CdxButton, CdxIcon } from '@wikimedia/codex';
import { cdxIconEdit } from '@wikimedia/codex-icons';
import { resolveDisplayProperties, type ResolvedProperty } from '@/domain/resolveDisplayProperties.ts';
import type { ViewProps } from '@/components/Views/ViewContract.ts';
import { EnclosingSubjectIdsKey } from '@/components/Value/ValueDisplayContract.ts';

const props = defineProps<ViewProps>();

provide( EnclosingSubjectIdsKey, computed( () => [ props.subjectId.text ] ) );

const subjectStore = useSubjectStore();
const schemaStore = useSchemaStore();
const layoutStore = useLayoutStore();
const subjectRepo = NeoWikiServices.getSubjectRepository();
const schemaRepo = NeoWikiServices.getSchemaRepository();

const { editingSubject, editingSchema, editorOpen, openEditor } = useSubjectEditor( subjectRepo, schemaRepo );

const subject = computed( () => subjectStore.getSubject( props.subjectId ) );
const schema = computed( () => schemaStore.getSchema( subject.value.getSchemaName() ) );

const handleSaveSubject = async (
	updatedSubject: Subject,
	dependentSubjects: DependentSubjects,
	comment: string
): Promise<void> => {
	await subjectStore.updateSubject( updatedSubject, dependentSubjects, comment );
};

const handleCreateSubject = async (
	subject: Subject,
	pageId: number,
	dependentSubjects: DependentSubjects,
	comment: string
): Promise<void> => {
	await subjectStore.createSubject( subject, pageId, dependentSubjects, comment );
};

const handleSaveSchema = async ( updatedSchema: Schema, comment: string ): Promise<void> => {
	await schemaStore.saveSchema( updatedSchema, comment );
};

function getComponent( propertyType: string ): Component {
	return NeoWikiServices.getComponentRegistry().getValueDisplayComponent( propertyType );
}

// Null when the Subject is already named after its Schema, so the heading above goes with the badge.
const schemaNameBadge = computed( (): string | null => schemaNameToShow( subject.value ) );

const layout = computed( () => {
	if ( !props.layoutName ) {
		return undefined;
	}
	return layoutStore.getLayout( props.layoutName );
} );

const displayRows = computed( () => expandUrlDisplayRows( resolvedProperties.value ) );

const resolvedProperties = computed( (): ResolvedProperty[] => {
	if ( !schema.value || !subject.value ) {
		return [];
	}
	return resolveDisplayProperties( schema.value, subject.value, layout.value, subjectStore.findSubject );
} );

</script>

<style lang="less">
